"""Kaggle entry point (generated by build_kernel.py).

The ``sparse_gt`` package and ``codes/`` are embedded below as a base64
tarball, unpacked into the working directory, tested, and then
``sparse_gt.experiments.<EXPERIMENT>`` is run. Results land in
``/kaggle/working/results/<EXPERIMENT>``.
"""

import base64
import io
import os
import subprocess
import sys
import tarfile
from pathlib import Path

BUNDLE = "@@BUNDLE@@"
EXTRA_ARGS = "@@ARGS@@"
EXPERIMENT = "@@EXPERIMENT@@"

work = Path("/kaggle/working") if Path("/kaggle/working").exists() else Path.cwd()
src = work / "src"
with tarfile.open(fileobj=io.BytesIO(base64.b64decode(BUNDLE)), mode="r:gz") as tar:
    try:
        tar.extractall(src, filter="data")
    except TypeError:  # Python without extraction filters
        tar.extractall(src)
pythonpath = os.pathsep.join(p for p in (str(src), os.environ.get("PYTHONPATH", "")) if p)
env = dict(os.environ, PYTHONPATH=pythonpath, SPARSE_GT_CODES_DIR=str(src / "codes"))

for module, package in (("pytest", "pytest"), ("pynvml", "nvidia-ml-py")):
    try:
        __import__(module)
    except ImportError:
        subprocess.run([sys.executable, "-m", "pip", "install", "-q", package], check=False)
tests = subprocess.run([sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider",
                        str(src / "sparse_gt" / "tests")], env=env)
if tests.returncode != 0:
    sys.exit("tests failed; not running the experiment")

subprocess.run(
    [sys.executable, "-u", "-m", f"sparse_gt.experiments.{EXPERIMENT}",
     "--out", str(work / "results" / EXPERIMENT), *EXTRA_ARGS.split()],
    env=env, check=True,
)
